import{_ as o,c as e,a3 as r,o as n}from"./chunks/framework.mrTHZ8pa.js";const d=JSON.parse('{"title":"Trouble Shooting","description":"","frontmatter":{},"headers":[],"relativePath":"local/troubleshooting.md","filePath":"local/troubleshooting.md"}'),a={name:"local/troubleshooting.md"};function l(i,t,s,u,c,g){return n(),e("div",null,t[0]||(t[0]=[r('<h1 id="trouble-shooting" tabindex="-1">Trouble Shooting <a class="header-anchor" href="#trouble-shooting" aria-label="Permalink to &quot;Trouble Shooting&quot;">​</a></h1><p>When a battery fault occurs, it will stop the operation of microgrid. To minimize the impact on your microgrid, please follow the instructions and procedures outlined below to clear the fault.</p><h2 id="battery-fault-clearing-procedure" tabindex="-1">Battery Fault Clearing Procedure <a class="header-anchor" href="#battery-fault-clearing-procedure" aria-label="Permalink to &quot;Battery Fault Clearing Procedure&quot;">​</a></h2><ol><li><strong>Battery Status</strong> indicates <strong>“Fault”</strong>.</li><li>Turn the <strong>rotary switch</strong> on the control cabinet to <strong>&quot;MAN&quot;</strong> mode.</li><li>Press and hold the <strong>“Off”</strong> button for 1 second under <strong>&quot;Battery Control&quot;</strong>.</li><li>After the Battery is off: <ul><li>Press and hold the <strong>&quot;Clear Fault&quot;</strong> button for 1 second.</li></ul><ul><li>The battery system will perform a self-check.</li><li>If <strong>Battery Status</strong> shows <strong>Initial State (DC Contactor Open)</strong>, it indicates that the fault has been cleared.</li><li>If the fault remains after 1 minute, contact ATI for assistance.</li></ul></li><li>Once the fault is cleared: <ul><li>Press and hold the <strong>“On”</strong> button under <strong>&quot;Battery Control&quot;</strong> to start the battery.</li><li>Turn the <strong>rotary switch</strong> on the control cabinet to <strong>&quot;Auto&quot;</strong> mode. The system is back to normal operation.</li></ul></li></ol><h2 id="temporary-microgrid-recovery-generator-only-mode" tabindex="-1">Temporary Microgrid Recovery (Generator-Only mode) <a class="header-anchor" href="#temporary-microgrid-recovery-generator-only-mode" aria-label="Permalink to &quot;Temporary Microgrid Recovery (Generator-Only mode)&quot;">​</a></h2><p>If a battery fault occurs but the microgrid urgently needs power, using the following methods to allow the generator to supply power independently.</p><ol><li>Ensure the <strong>AUTO/MAN rotary switch</strong> is set to the <strong>&quot;MAN&quot;</strong> position.</li><li>On the system overview page, start the generator by perssing <strong>On</strong> button under <strong>Generator Control</strong>.</li><li>Once started, the generator will supply power to the loads.</li></ol>',7)]))}const p=o(a,[["render",l]]);export{d as __pageData,p as default};
